import type { ReactNode } from "react";
import styles from "./nav-tabs.module.css";

type Item = { label: ReactNode; href?: string; active?: boolean; onClick?: () => void; count?: number };
export function NavTabs({ label, items, className }: { label: string; items: Item[]; className?: string }) {
  return <nav className={[styles.tabs, className].filter(Boolean).join(" ")} aria-label={label}><span className={styles.label}>{label}</span>{items.map((item, index) => item.href ? <a key={index} className={[styles.link, item.active ? styles.active : undefined].filter(Boolean).join(" ")} href={item.href} aria-current={item.active ? "page" : undefined}>{item.label}{item.count !== undefined && <span className={styles.count}>{item.count}</span>}</a> : <button key={index} type="button" className={[styles.link, item.active ? styles.active : undefined].filter(Boolean).join(" ")} onClick={item.onClick} aria-current={item.active ? "page" : undefined}>{item.label}</button>)}</nav>;
}
