"use client";

import businessStyles from "@/components/business.module.css";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { userFeedback } from "@/lib/user-feedback";
import { Button } from "@/components/ui/button";
import { TextField } from "@/components/ui/form-controls";
import { FeedbackMessage } from "@/components/ui/feedback-message";

type ContainerDraft = { id?: string; internalCode?: string; containerType: string; containerNo?: string | null };

export function ContainerAdjustmentForm({
  orderId,
  initialContainers,
}: {
  orderId: string;
  initialContainers: ContainerDraft[];
}) {
  const [containers, setContainers] = useState(initialContainers);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const router = useRouter();
  function update(index: number, containerType: string) {
    setContainers((current) =>
      current.map((item, position) =>
        position === index ? { ...item, containerType } : item,
      ),
    );
  }
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    const form = new FormData(event.currentTarget);
    const next = containers.map(({ id, containerType }) => ({ id, containerType: containerType.trim() }));
    if (!next.length || next.some((item) => !item.containerType)) {
      setMessage("请为每个柜位填写柜型。");
      return;
    }
    setBusy(true);
    setMessage("");
    try {
      const response = await fetch(`/api/orders/${orderId}/containers/adjust`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ reason: form.get("reason"), containers: next }),
      });
      if (response.ok) {
        setMessage("柜位与柜型已保存。");
        router.refresh();
      } else setMessage(userFeedback.retry("保存柜量调整"));
    } catch {
      setMessage(userFeedback.network);
    } finally {
      setBusy(false);
    }
  }
  return (
    <section className={businessStyles["container-adjustment-section"]}>
      <h3>内部柜位与柜型</h3>
      <p className={businessStyles["muted"]}>
        一个内部柜位对应一个后续实际柜号。先在这里逐柜位确认柜型；装柜完成后，再按内部柜号登记对应的实际柜号。已有装柜计划时请先调整或取消对应计划。
      </p>
      <form className={businessStyles["container-adjustment-form"]} onSubmit={submit}>
        <div className={businessStyles["container-adjustment-form__rows"]}>
          {containers.map((item, index) => (
            <div className={businessStyles["container-adjustment-form__row"]} key={index}>
              <div className={businessStyles["container-adjustment-form__code"]}>
                <span>内部柜号</span>
                <b>{item.internalCode || "新增柜位（保存后生成）"}</b>
                {item.containerNo && <small>实际柜号：{item.containerNo}</small>}
              </div>
              <TextField className={businessStyles["container-adjustment-form__type"]} label="柜型" value={item.containerType} placeholder="例如：40HQ" disabled={busy} onChange={(event) => update(index, event.target.value)} />
              {containers.length > 1 && (
                <Button
                  variant="text"
                  disabled={busy}
                  type="button"
                  onClick={() =>
                    setContainers((current) =>
                      current.filter((_, position) => position !== index),
                    )
                  }
                >
                  移除
                </Button>
              )}
            </div>
          ))}
        </div>
        <Button
          variant="neutral"
          size="small"
          disabled={busy}
          type="button"
          onClick={() =>
            setContainers((current) => [
              ...current,
              { containerType: "" },
            ])
          }
        >
          新增柜位
        </Button>
        <TextField className={businessStyles["container-adjustment-form__reason"]} label="调整说明" name="reason" placeholder="例如：客户新增 1 个 40HQ，或取消内部柜号 IC-XXX-002" required disabled={busy} />
        <Button type="submit" size="small" disabled={busy}>{busy ? "正在保存…" : "保存"}</Button>
        {message && (
          <FeedbackMessage>{message}</FeedbackMessage>
        )}
      </form>
    </section>
  );
}
